function createEnv(sdk) {
  var MAX_STEPS = 1200;
  var DT = 1 / 60;
  var TRACK_LIMIT = 2.4;
  var ANGLE_LIMIT = 12 * Math.PI / 180;
  var cartMass = 1;
  var poleMass = 0.1;
  var halfPoleLength = 0.5;
  var gravity = 9.8;
  var forceMagnitude = 10;

  var rng, x, xDot, angle, angleDot, steps, done;
  var terms = [0, 0, 0];
  var obs = [0, 0, 0, 0];

  function reset(seed) {
    rng = sdk.rng(seed);
    x = rng.range(-0.05, 0.05);
    xDot = rng.range(-0.03, 0.03);
    angle = rng.range(-0.045, 0.045);
    angleDot = rng.range(-0.03, 0.03);
    steps = 0;
    done = false;
    terms[0] = 0;
    terms[1] = 0;
    terms[2] = 0;
  }

  return {
    reset: reset,

    step: function (action) {
      if (done) return;

      var force = 0;
      if (action === 0) force = -forceMagnitude;
      else if (action === 2) force = forceMagnitude;

      var sinA = Math.sin(angle);
      var cosA = Math.cos(angle);
      var totalMass = cartMass + poleMass;
      var temp = (force + poleMass * halfPoleLength * angleDot * angleDot * sinA) / totalMass;
      var angleAcc = (gravity * sinA - cosA * temp) /
        (halfPoleLength * (4 / 3 - poleMass * cosA * cosA / totalMass));
      var cartAcc = temp - poleMass * halfPoleLength * angleAcc * cosA / totalMass;

      xDot += cartAcc * DT;
      angleDot += angleAcc * DT;
      x += xDot * DT;
      angle += angleDot * DT;

      steps += 1;
      var angleQuality = sdk.clamp(1 - Math.abs(angle) / ANGLE_LIMIT, 0, 1);
      var positionQuality = sdk.clamp(1 - Math.abs(x) / (TRACK_LIMIT * 2), 0, 1);
      terms[0] += angleQuality * positionQuality / MAX_STEPS;
      terms[1] += 1 / MAX_STEPS;
      if (force !== 0) terms[2] += 1 / MAX_STEPS;

      if (Math.abs(x) > TRACK_LIMIT || Math.abs(angle) > ANGLE_LIMIT || steps >= MAX_STEPS) {
        done = true;
      }
    },

    observe: function () {
      obs[0] = sdk.clamp(x / TRACK_LIMIT, -1, 1);
      obs[1] = sdk.clamp(xDot / 3, -1, 1);
      obs[2] = sdk.clamp(angle / ANGLE_LIMIT, -1, 1);
      obs[3] = sdk.clamp(angleDot / 4, -1, 1);
      return obs;
    },

    get done() {
      return done;
    },

    terms: terms,

    render: function (draw, ghost) {
      if (!ghost) {
        draw.clear(sdk.colors.bg);
        draw.line(45, 390, 755, 390, sdk.colors.dim, 3);
        draw.line(100, 402, 700, 402, sdk.colors.dim, 1);
        draw.text("Keep the pole upright", 24, 35, sdk.colors.fg, 18);
      }

      var cartX = 400 + x * 120;
      var cartY = 365;
      var poleX = cartX + Math.sin(angle) * 95;
      var poleY = cartY - Math.cos(angle) * 95;

      draw.rect(cartX - 34, cartY - 15, 68, 28, sdk.colors.accent);
      draw.circle(cartX - 21, cartY + 17, 8, sdk.colors.fg);
      draw.circle(cartX + 21, cartY + 17, 8, sdk.colors.fg);
      draw.line(cartX, cartY - 12, poleX, poleY, sdk.colors.warn, 8);
      draw.circle(poleX, poleY, 7, sdk.colors.good);
    },

    humanAct: function (input) {
      if (input.held.has("ArrowLeft")) return 0;
      if (input.held.has("ArrowRight")) return 2;
      return 1;
    }
  };
}
